mapper.delete:
DELETE FROM admin_legacy_application_keyword
WHERE research_no = #{researchNo}
  AND research_app_seq = #{researchAppSeq}

mapper.select:
SELECT keyword.research_no, keyword.research_app_seq, COUNT(DISTINCT keyword.keyword_normalized) AS match_score FROM admin_legacy_application_keyword keyword WHERE keyword.keyword_normalized IN
#{includeKeyword}
AND keyword.research_no != #{currentResearchNo} AND LEFT(REGEXP_REPLACE(COALESCE(keyword.application_regist_dt, ''), '[^0-9]', ''), 8) >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 2 YEAR), '%Y%m%d')
AND NOT EXISTS ( SELECT 1 FROM admin_legacy_application_keyword excluded WHERE excluded.research_no = keyword.research_no AND excluded.research_app_seq = keyword.research_app_seq AND excluded.keyword_normalized IN
#{excludeKeyword}
)
GROUP BY keyword.research_no, keyword.research_app_seq ORDER BY match_score DESC, keyword.research_app_seq DESC LIMIT #{limit}
